import re

def parsear_duracion(s: str) -> int:
    total_minutos = 0

    # Patrón para encontrar horas (h) y minutos (m)
    # Busca un número seguido de 'h' o 'm'
    matches = re.findall(r'(\d+)([hm])', s)

    for value_str, unit in matches:
        value = int(value_str)
        if unit == 'h':
            total_minutos += value * 60
        elif unit == 'm':
            total_minutos += value

    return total_minutos

