def from_romano(s: str) -> int:
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0

    # Iterar de derecha a izquierda para manejar la notación sustractiva fácilmente
    for char in reversed(s):
        value = roman_map[char]

        if value < prev_value:
            total -= value
        else:
            total += value

        prev_value = value

    return total

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = (lista[0], 0)
    actual_elemento = lista[0]
    actual_longitud = 0

    for elemento in lista:
        if elemento == actual_elemento:
            actual_longitud += 1
        else:
            # Comprobar si la racha anterior es la más larga
            if actual_longitud > max_racha[1]:
                max_racha = (actual_elemento, actual_longitud)

            # Reiniciar para el nuevo elemento
            actual_elemento = elemento
            actual_longitud = 1

    # Comprobar la última racha después del bucle
    if actual_longitud > max_racha[1]:
        max_racha = (actual_elemento, actual_longitud)

    return max_racha

