def romano_a_int(romano):
    mapa = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(romano):
        siguiente_valor = mapa[romano[i]]
        if i + 1 < len(romano):
            siguiente_valor_siguiente = mapa[romano[i+1]]
            if siguiente_valor_siguiente < siguiente_valor:
